AddCSLuaFile()

SWEP.Base = "cw_anomaly_desert_eagle_nimble"

SWEP.PrintName = "Desert Eagle “Steppe Eagle” (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "slide"
