	SWEP.BoltBonePositionRecoverySpeed = 44
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_desert_eagle_nimble_vmrecoil",
		"vgui/killicons/tfa_anomaly_desert_eagle_nimble", Color(255, 255, 255))
end

